// SP Wallet core API v1 — the CONTRACT of everything a wallet client uses outside /api/v1/trading: what each route takes,
// what it answers, which error codes it can give, and which enumerations a client must decode tolerantly.
//
// Same pattern as the trading API (trading-api/spec.ts): this file is pure (zod and two pure tables — no configuration, no
// database, no signer), so that the OpenAPI document, the TypeScript types of the web app and the route table of
// docs/next/SP-WALLET-API.md are generated by a script and by tests without starting anything.
//
// Difference with the trading API, stated once: the wallet routes are NOT registered from this table. They were written
// before it and shipped native apps decode their answers, so this table DESCRIBES them and two tests keep it honest:
//   - test/wallet-contract.test.ts calls every route on the real server and validates each answer against the document
//     (in strict mode: a member the code returns and the table does not declare fails the test);
//   - the same test enumerates the routes Fastify registered under /api/v1 and fails when one is in neither this table nor
//     the allow-list of the families documented elsewhere (`OTHER_FAMILIES`).
// Request schemas are copies of the routes' own zod schemas (those are not exported, and their modules are not pure).
//
// Conventions of every answer (docs/next/SP-WALLET-ARCHITECTURE.md, "API rules"):
//   additive     no member is removed, renamed or retyped; objects are open (a client ignores what it does not know);
//   amounts      strings of base units, with a display string computed by exact arithmetic — never a float;
//   estimates    a figure that is an estimate, partial or stale carries the member that says so;
//   enums        every enumeration is named in `ENUMS` with `open`: true = new values may appear, decode with a fallback.
import { z } from 'zod';
import { ALERT_KINDS, CRED_MAX_TTL_SEC, LIFECYCLES, STATES } from '@spw/core'; // pure tables: the two vocabularies of a transfer, the alert catalogue
import { SV } from '../sv-texts.ts'; // pure: the catalogue of server-authored outcome sentences

export const WALLET_PREFIX = '/api/v1';
export const WALLET_API_VERSION = '1.0.0';

// ---------------------------------------------------------------------------------------------------------------- enumerations
export interface EnumDoc {
  values: readonly string[];
  /** true: the server may answer a value that is not in `values` in a later release — decode with an "unknown" fallback */
  open: boolean; description: string;
  /** what each value means, when it needs saying */
  docs?: Record<string, string>;
  /** an open enumeration can also carry values of these families (a prefix): codes written by another component, passed through */
  prefixes?: readonly string[];
}
/** `errorCode` of a proposal that ended or is held back: the outcome section of sv-texts.ts (holds and plan codes have their own fields) */
export const PROPOSAL_OUTCOME_CODES = (Object.keys(SV) as string[]).filter((k) => !k.startsWith('hold_') && !k.startsWith('plan_'));
/** Warnings of a transfer review (`warnings` of a proposal). `ack`: the clients make the owner tick a box before the passkey is asked
 *  (a client-side rule — the server does not enforce it: web `Send.tsx` for the first two, transfers.ts `duplicateWarning` for the third). */
export const TRANSFER_WARNINGS: Record<string, { meaning: string; ack: boolean; emitted: boolean }> = {
  new_destination: { meaning: 'the wallet never sent to this address and it is not in the address book', ack: true, emitted: true },
  address_poisoning_suspected: { meaning: 'the address differs from a known one but starts and ends with the same characters: the classic look-alike of an address-poisoning attack', ack: true, emitted: true },
  duplicate_recent: { meaning: 'the same asset, amount and destination was sent, or may have been sent, in the last 24 hours', ack: true, emitted: true },
  contract_destination: { meaning: 'the destination is a contract (EVM) or a program-owned account (Solana), not a plain wallet: it may not be able to use what it receives', ack: false, emitted: true },
  network_congested: { meaning: 'the network is congested: the fee is capped, so the transfer may expire without being included (nothing moves in that case)', ack: false, emitted: true },
  creates_account: { meaning: 'the destination account does not exist yet on this network: the transfer creates it and part of the amount stays locked as its reserve', ack: false, emitted: true },
  creates_token_account: { meaning: 'Solana: the destination has no account for this token; the transfer creates it and the sender pays its rent', ack: false, emitted: true },
  near_creates_account: { meaning: 'NEAR: the destination account does not exist yet; the transfer creates it, which adds a fee paid by the sender', ack: false, emitted: true },
  activates_account: { meaning: 'the address was never used on this network: activating it is charged to the sender on top of the amount (TRON)', ack: false, emitted: true },
  deploys_wallet: { meaning: 'TON: the first outgoing transfer also deploys the wallet contract (slightly higher fee, cannot be simulated beforehand)', ack: false, emitted: true },
  destination_not_initialized: { meaning: 'TON: no contract is deployed at the destination (a new wallet, or a wrong address); the funds are credited there and cannot bounce back', ack: false, emitted: true },
  memo_numeric_id: { meaning: 'Stellar: the memo is digits only and is sent as a numeric id (MEMO_ID), the format exchanges expect', ack: false, emitted: true },
  dt_new_account: { meaning: 'Polkadot Asset Hub: the destination account does not exist yet; this transfer creates it and it must always keep the existential deposit', ack: false, emitted: true },
  cd_token_outputs: { meaning: 'Cardano: some outputs of this wallet carry native tokens or script data; they are never spent and their ADA stays locked with them', ack: false, emitted: true },
  l1_fee_unknown: { meaning: 'OP-stack networks: the L1 data fee could not be read; the fee ESTIMATE covers the L2 part only and the chain charges the data fee on top (it is not a field the signer can bound)', ack: false, emitted: true },
};
export const EVENT_TYPES: Record<string, string> = {
  'transfer.state': 'a proposal changed state — `data`: `{ from, to, lifecycle, network, kind, txid, confirmations, errorCode }`; `ref` = proposal id',
  'transfer.relay': 'a relay of the signed transaction to the network started (its outcome is not known yet) — `data`: `{ network, lifecycle: "broadcasting", txid }`',
  'transfer.confirmations': 'the confirmation count of a tracked transaction changed — `data`: `{ network, confirmations, txid }`',
  'deposit.seen': 'an incoming payment was recorded — `data`: `{ network, txid, asset, amount, kind, origin?, proposal?, detection? }`',
  'deposit.native_window': 'EVM native-coin scan: a balance difference was located to a block window, not to a transaction',
  'deposit.scan_gap': 'a transaction of the deposit scan is no longer served by any source',
  'device.added': 'a passkey was added — `data`: `{ credential, label }`',
  'device.revoked': 'a passkey was revoked — `data`: `{ credential, label, signer, sessions, ip }` (`signer`: it was on the signer\'s list; `sessions`: sessions it had opened, ended with it)',
  'session.revoked': 'one session was revoked by its public id — `data`: `{ session, current, ip }`',
  'credentials.mismatch': 'the signer\'s passkey list and the API\'s differ, and still did 30 s later — `data`: `{ count, signerOnly, apiOnly }` (12-character id prefixes)',
  'credentials.reconciled': 'the two passkey lists agree again',
  'settings.saved': 'account settings changed — `data`: `{ changed: { locale?, currency?, hideBalances?, prices?, theme? } }`: re-read GET /settings',
  'sessions.revoked': 'every session was revoked',
  'login.ok': 'a sign-in succeeded — `data`: `{ credential, ip, label, device, newDevice, session }`',
  'owner.setup': 'the first passkey was enrolled (one-time setup)',
  'addressbook.saved': 'a contact was created or changed — `data`: `{ network, address, label }`',
  'addressbook.removed': 'a contact was deleted',
  'settings.asset_pref': 'an asset was hidden / shown / made favourite — `data`: `{ network, asset, hidden, favorite }`',
  'halt.on': 'the emergency halt of the signer was triggered',
  'security.contact_address_changed': 'a contact now points to another address — `data`: `{ id, network, label, from, to }`',
};
const LIFECYCLE_DOCS: Record<(typeof LIFECYCLES)[number], string> = {
  draft: 'prepared, nothing frozen; expires by itself',
  awaiting_confirmation: 'the exact transaction is frozen and shown; the passkey has not been given',
  awaiting_signature: 'the passkey was given; the signer call is in flight',
  signed: 'signed; no relay to the network has started',
  broadcasting: 'signed and a relay has started: from here only the chain can say that nothing was sent',
  pending: 'handed to the network, not in a block yet',
  confirming: 'in a block, not final (see `confirmations`); a reorganisation can still undo it',
  confirmed: 'FINAL. The only value a client may treat as done',
  failed: 'ended without effect, or reverted on-chain (`errorCode` says which)',
  replaced: 'another transaction used the same nonce or coins. Still re-checked for a day (`watched`): it becomes confirming / confirmed if it turns out to be in a block',
  dropped: 'no source knows it and nothing proves it dead. NOT a failure: it stays watched and is recorded if it appears; a new send on the network replaces it',
  expired: 'the approval window passed before the passkey, or the validity window of the signed transaction closed on-chain (`errorCode: expired_onchain`); nothing moved',
  rejected: 'rejected by the owner before signing',
  not_sent: 'signed and deliberately not relayed (broadcasting is disabled on this server)',
};
export const ENUMS = {
  ProposalState: { values: STATES.filter((s) => s !== 'dropped'), open: false,
    description: 'Stored state in the vocabulary shipped clients know. FROZEN: no value is ever added here (native builds decode it with a closed enum); a `dropped` transfer reads `failed` with `errorCode: dropped`. New clients read `lifecycle`.' },
  Lifecycle: { values: LIFECYCLES, open: true, docs: LIFECYCLE_DOCS,
    description: 'The life cycle of a transfer as a client shows it — one vocabulary for web, macOS and iOS. Only `confirmed` means done.' },
  ProposalKind: { values: ['transfer', 'swap', 'bridge', 'xswap', 'gmx', 'nft'], open: true, description: 'What a proposal is: a plain transfer, a same-network swap, a CCTP bridge, a native cross-chain swap, a GMX order transaction, an NFT transfer.' },
  ActivityRowKind: { values: ['send', 'receive', 'swap', 'bridge', 'gmx'], open: true, description: 'What a row of GET /activity is. `rawKind` keeps the stored proposal kind (xswap is shown with the swaps).' },
  TransferWarning: { values: Object.keys(TRANSFER_WARNINGS), open: true, docs: Object.fromEntries(Object.entries(TRANSFER_WARNINGS).map(([k, v]) => [k, `${v.meaning}${v.ack ? ' — to acknowledge before approving' : ''}${v.emitted ? '' : ' — reserved, not emitted by this version'}`])),
    description: 'Warning codes of a transfer review. A client shows an unknown code as a generic caution.' },
  ProposalErrorCode: { values: PROPOSAL_OUTCOME_CODES, open: true, prefixes: ['signer_'], docs: Object.fromEntries(PROPOSAL_OUTCOME_CODES.map((k) => [k, (SV as Record<string, string>)[k]!])),
    description: 'Why a proposal ended or is held (`errorCode`; `error` is the English sentence, `errorParams` its parameters). A signer refusal carries the signer\'s own code, prefixed `signer_`.' },
  DepositKind: { values: ['external', 'internal'], open: true, description: 'external = someone paid the wallet; internal = the result of one of the wallet\'s own operations (`origin` says which).' },
  DepositOrigin: { values: ['transfer', 'swap', 'bridge', 'xswap', 'gmx', 'nft', 'agent_withdrawal', 'venue_withdrawal'], open: true, description: 'The own operation an internal deposit comes from. `agent_withdrawal` and `venue_withdrawal` come back from the owner\'s own accounts outside the wallet.' },
  DepositDetection: { values: ['tx', 'internal_call', 'aggregate'], open: true, description: 'How a native-coin deposit was located: its transaction, a contract call inside a block, or a balance difference over a block window (`txidIsBlock`).' },
  FlowScope: { values: ['external', 'internal', 'ownAccounts'], open: false, description: 'Classification of a movement: external (in from / out to someone else), internal (the wallet\'s own swaps, bridges, self-transfers: nothing entered or left), ownAccounts (to / from the owner\'s agent vaults and venue accounts).' },
  EventType: { values: Object.keys(EVENT_TYPES), open: true, docs: EVENT_TYPES, description: 'Types of the wallet event log. Every audit type matching deposit.*, device.*, session(s).*, addressbook.*, settings.*, halt.*, security.* is mirrored: new types appear without notice.' },
  AlertKind: { values: ALERT_KINDS, open: true, description: 'Kind of an alert (packages/core/src/alert-catalog.ts, which also holds its FR / EN wording). A release adds kinds: show an unknown one with its `kind` and severity.' },
  AlertSeverity: { values: ['info', 'warning', 'critical'], open: false, description: 'Severity of an alert.' },
  AlertGroup: { values: ['transfers', 'agents', 'derivatives', 'security', 'system'], open: true, description: 'Group of an alert kind.' },
  Currency: { values: ['USD', 'CAD'], open: false, description: 'Display currency.' },
  SearchMatch: { values: ['symbol', 'name', 'network', 'contract', 'label', 'address', 'note', 'txid', 'amount'], open: true, description: 'Which member of a search result matched the query.' },
} as const satisfies Record<string, EnumDoc>;
export type EnumName = keyof typeof ENUMS;
/** a member whose values are one of `ENUMS`: a closed list is a JSON-Schema `enum`; an open one is a string that names its list */
const En = (name: EnumName): z.ZodType<string> => {
  const e: EnumDoc = ENUMS[name];
  return (e.open ? z.string() : z.enum(e.values as [string, ...string[]])).meta({ 'x-spw-enum': name });
};
/** a shape the document names once under components */
const component = <T extends z.ZodType>(name: string, s: T): T => s.meta({ 'x-spw-component': name }) as T;

// ---------------------------------------------------------------------------------------------------------------- shared shapes
