// ---------------------------------------------------------------------------------------------------------------- requests
const UuidParam = z.object({ id: z.string().describe('the id returned by the creation or by a list') });
const Limit = (dflt: number, max: number) => z.coerce.number().int().min(1).max(max).default(dflt).describe('rows returned at most');
const NO_CONTROL = /^[^\u0000-\u001f\u007f]*$/;
const NetworkFilter = z.string().min(1).max(20).regex(NO_CONTROL).optional().describe('NEXT: only the movements on this network id');
const AssetFilter = z.string().min(1).max(130).regex(NO_CONTROL).optional().describe('NEXT: only the movements of this asset id (`native` or a contract / mint address); use it with `network`');
const TransferCreate = z.strictObject({ network: z.string().max(20), asset: z.string().max(80), to: z.string().min(1).max(130), amount: z.string().min(1).max(80).describe('decimal string in the asset\'s own unit'), note: z.string().max(80).default(''), memo: z.string().max(120).optional() });
const RegBody = z.object({ challengeId: z.uuid(), response: z.any().describe('the WebAuthn registration response'), setupToken: z.string().min(8).max(100).optional(), label: z.string().max(40).optional() });
const AuthBody = z.object({ challengeId: z.uuid(), response: z.any().describe('the WebAuthn assertion') });
const DashFilters = { kind: z.string().optional(), mode: z.enum(['live', 'paper', 'research']).optional(), venue: z.string().min(1).max(40).optional(), principal: z.enum(['owner', 'agent', 'api_key', 'system']).optional(), from: z.string().max(40).optional(), to: z.string().max(40).optional(),
  network: NetworkFilter, asset: AssetFilter };

// ---------------------------------------------------------------------------------------------------------------- errors
export interface ErrorDecl { status: number; code: string }
const E = (status: number, ...codes: string[]): ErrorDecl[] => codes.map((code) => ({ status, code }));
/** code → [what it means, what the client does]. Every code of every operation is here (a test fails otherwise). */
export const WALLET_ERRORS: Record<string, [meaning: string, action: string]> = {
  unauthenticated: ['no valid session', 'sign in with the passkey, then repeat the request'],
  csrf: ['a mutating request without the same-origin proof (`Origin` + `X-SPW-CSRF: 1`)', 'send both headers; never retry from another origin'],
  bad_request: ['the request is not valid; `data.fields` lists the refused members when it comes from input validation', 'fix the request; do not retry unchanged'],
  rate_limited: ['too many requests from this address', 'wait a minute'],
  internal: ['server error', 'retry later; a transfer approval is NOT retried blindly — re-read the proposal first'],
  not_found: ['the object does not exist', 'reload the list'],
  conflict: ['the object changed concurrently', 'reload it, then decide again'],
  timeout: ['a source did not answer in time', 'retry later'],
  owner_only: ['the route is for the owner\'s session, not an API key', 'use the session'],
  key_path_forbidden: ['an API key was sent outside /api/v1/trading', 'use the session'],
  signer_unreachable: ['the signer cannot be reached; nothing was signed', 'reads still work; retry sending later'],
  unsupported_network: ['the signer has no key for this network', 'do not offer this network'],
  // authentication
  setup_closed: ['the one-time setup was already completed', 'sign in instead'],
  setup_token: ['the setup token is missing', 'ask for the token printed by the signer'],
  challenge_expired: ['the challenge expired or was already used', 'ask for new options and try again'],
  registration_failed: ['the passkey registration could not be verified', 'try again'],
  login_failed: ['authentication failed (unknown passkey or bad assertion)', 'try again; repeated failures raise an alert'],
  expired: ['the approval window, or the pending passkey, expired', 'start again'],
  last_credential: ['the last passkey on the signer cannot be revoked', 'add another passkey first'],
  no_approver: ['no other passkey can approve this revocation (none enrolled on the signer and out of its cool-down)', 'wait for the cool-down of the other passkey, or add one'],
  self_approval: ['a passkey cannot approve its own revocation', 'approve with another passkey'],
  bad_approval: ['the approval could not be verified against the signer\'s list', 'approve again with a passkey the signer lists'],
  // transfers
  idempotency: ['the `Idempotency-Key` header is missing or malformed (16–64 letters, digits, dashes)', 'send one key per intended transfer'],
  idempotency_mismatch: ['this Idempotency-Key was already used for a different request', 'use a new key'],
  unsupported_asset: ['the asset is not in the verified registry of this network', 'pick an asset of GET /assets'],
  bad_address: ['the destination is not a valid address of this network, or is the wallet itself', 'correct the address'],
  bad_amount: ['the amount is not a positive decimal within the asset\'s precision', 'correct the amount'],
  bad_memo: ['the memo / destination tag is not accepted on this network', 'correct or remove it'],
  bad_destination: ['the destination cannot receive this asset (account type, missing trust line…)', 'check the destination'],
  bad_source: ['the wallet\'s own account cannot send this asset in its present state', 'see the message'],
  memo_required: ['the destination requires a memo / tag', 'add it'],
  contract_destination: ['the destination is a contract that cannot receive this transfer', 'check the destination'],
  insufficient_funds: ['the balance does not cover the amount and the fee', 'lower the amount'],
  insufficient_gas: ['not enough of the network\'s native coin to pay the fee', 'fund the native coin'],
  insufficient_unlocked_funds: ['part of the balance is locked', 'lower the amount'],
  below_rent: ['the transfer would leave an account below its rent-exempt minimum', 'change the amount'],
  below_reserve: ['the transfer would leave the account below the network reserve', 'change the amount'],
  too_many_coins: ['too many small coins are needed for this amount', 'send a smaller amount first'],
  unsupported_account: ['the account type is not supported', 'see the message'],
  unsupported_funds: ['the balance is of a kind this wallet does not spend', 'see the message'],
  fee_too_high: ['the network fee is above the wallet\'s ceiling right now, or could not be established', 'retry later'],
  fee_ceiling: ['the fee needed exceeds the signer\'s ceiling', 'retry later'],
  rpc_degraded: ['not enough data sources answered for this network; nothing was prepared', 'retry later'],
  rpc_disagreement: ['the data sources disagree; nothing was prepared', 'retry later'],
  protocol_changed: ['the network\'s protocol changed since this wallet was reviewed; sending is suspended', 'update the wallet'],
  runtime_changed: ['the network\'s runtime changed since this wallet was reviewed; sending is suspended', 'update the wallet'],
  simulation_failed: ['the exact transaction could not be built or would fail now', 'see the message; nothing was signed'],
  policy: ['the signer\'s policy refuses it (limit per transfer, per day, asset not allowed, halt)', 'see the message; limits are changed on the signer only'],
  halted: ['the emergency halt is active', 'nothing can be signed until the halt is lifted on the signer'],
  pending_tx: ['another transfer or swap on this network is not confirmed yet', 'wait for it; a dropped one no longer blocks'],
  bad_state: ['the proposal is not in a state that allows this', 're-read the proposal and show its real state'],
  hash_mismatch: ['the signer answered another intent hash; the transfer was marked failed', 'report it; nothing was sent'],
  // address book, preferences
  stale_contact: ['the contact changed since it was read', 'reload it before changing its address'],
  duplicate_contact: ['another contact already has this address', 'edit that contact'],
  // alerts, push, streams
  too_many_streams: ['too many event streams are open', 'close one, or fall back to polling'],
  too_many_subscriptions: ['too many push devices', 'remove one'],
  invalid_cursor: ['the cursor is not one a previous page returned', 'restart from the first page'],
};
const C = {
  session: [...E(401, 'unauthenticated'), ...E(429, 'rate_limited'), ...E(500, 'internal')],
  public: [...E(429, 'rate_limited'), ...E(500, 'internal')],
  signer: E(503, 'signer_unreachable'),
  chain: [...E(400, 'bad_destination', 'bad_source', 'memo_required', 'contract_destination', 'insufficient_funds', 'insufficient_gas', 'insufficient_unlocked_funds', 'below_rent', 'below_reserve', 'too_many_coins', 'unsupported_account', 'unsupported_funds', 'fee_too_high', 'simulation_failed', 'pending_tx'),
    ...E(409, 'pending_tx'), ...E(422, 'fee_ceiling'), ...E(503, 'fee_too_high', 'rpc_degraded', 'rpc_disagreement', 'protocol_changed', 'runtime_changed', 'unsupported_network')],
  proposal: E(404, 'not_found'),
};

// ---------------------------------------------------------------------------------------------------------------- operations
export const TAGS = ['Meta', 'Auth', 'Wallet', 'Portfolio', 'Transfers', 'Activity', 'AddressBook', 'Settings', 'Security', 'Alerts', 'Events', 'Dashboard', 'Analytics', 'Search'] as const;
export type WalletTag = (typeof TAGS)[number];
export interface WalletOp {
  /** operationId */
  id: string; method: 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE';
  /** full Fastify path (`:name` parameters) */
  path: string; tag: WalletTag; summary: string; description?: string;
  /** public: no session. Every other route needs the owner session cookie; a mutating call also needs `Origin` + `X-SPW-CSRF: 1` */
  auth: 'public' | 'session';
  params?: z.ZodObject; query?: z.ZodObject; body?: z.ZodType; response?: z.ZodType;
  /** the 200 answer is not JSON */
  produces?: 'text/csv' | 'text/event-stream';
  /** the `Idempotency-Key` header is required */
  idempotencyKey?: boolean;
  /** beyond what `errorsOf` adds for every operation */
  errors?: readonly ErrorDecl[];
  /** true: a chain adapter or the signer can add a code of its own (`signer_<code>`) */
  errorsOpen?: boolean;
  /** added by SP Wallet NEXT */
  next?: boolean;
}
const op = (id: string, method: WalletOp['method'], path: string, tag: WalletTag, summary: string, o: Partial<WalletOp> = {}): WalletOp => ({ id, method, path: WALLET_PREFIX + path, tag, summary, auth: 'session', ...o });

