export const operation = (id: string): WalletOp => { const o = OPERATIONS.find((x) => x.id === id); if (!o) throw new Error(`unknown wallet operation ${id}`); return o; };

/** Every error answer of one operation: what its position implies (session, CSRF, validation) and what its handler adds. */
export function errorsOf(o: WalletOp): ErrorDecl[] {
  const all: ErrorDecl[] = [...(o.auth === 'session' ? C.session : C.public)];
  if (o.method !== 'GET') all.push(...E(403, 'csrf'));
  if (o.params || o.query || o.body || o.method !== 'GET') all.push(...E(400, 'bad_request'));
  all.push(...(o.errors ?? []));
  const seen = new Set<string>();
  return all.filter((e) => { const k = `${e.status} ${e.code}`; if (seen.has(k)) return false; seen.add(k); return true; }).sort((a, b) => a.status - b.status || (a.code < b.code ? -1 : a.code > b.code ? 1 : 0));
}

